// mysql_guard — separate successful results from MySQL-node errors

function fail(reason) {
    msg.payload = {
        answer: '❌ Error executing the SQL query against the database: ' + reason,
        columns: [],
        rows: [],
        sql: msg.sql || msg.topic || '',
        via: msg.via || 'web',
        suggestions: [
            'Check that column names are correct (for example, L rather than Luz).',
            'Rephrase the question with more detail.'
        ]
    };
    return [null, msg]; // output 2 -> HTTP response
}

// Explicit error case: msg.error
if (msg.error) {
    return fail(msg.error.message || String(msg.error));
}

// Error case: payload is an Error or an unexpected value
if (msg.payload instanceof Error) {
    return fail(msg.payload.message || String(msg.payload));
}

// If payload is NOT an array (the normal MySQL-node result),
// treat it as a generic error.
if (!Array.isArray(msg.payload)) {
    const p = msg.payload || {};
    const reason = p.sqlMessage || p.message || JSON.stringify(p);
    return fail(reason);
}

// Success case: msg.payload contains database rows (an array)
return [msg, null];

// Read identity settings from environment variables, with fallback defaults
const NAME     = env.get('ABOUT_NAME')     || 'QUILLAMA';
const VERSION  = env.get('ABOUT_VERSION')  || '0.1.0';
const OWNER    = env.get('ABOUT_OWNER')    || 'Quillaqua';
const MISSION  = (env.get('ABOUT_MISSION') || 'Greenhouse climate analyst. I summarise data, detect anomalies, and provide operational recommendations based on SQL readings.').trim();
const TONE     = (env.get('ABOUT_TONE')    || 'Clear, concise, and actionable.').trim();
const GUARDS   = (env.get('ABOUT_GUARDS')  || 'I do not invent values. I use only SQL data. If no data are available, I say so. I do not execute actions; I only provide recommendations.').trim();

const LLM_SQL     = env.get('LLM_MODEL')         || 'qwen2.5-coder:14b';
const LLM_SUMMARY = env.get('LLM_SUMMARY_MODEL') || 'qwen2.5:14b';

const APP_TZ   = env.get('APP_TZ')        || 'America/Guayaquil';
const APP_OFF  = env.get('APP_TZ_OFFSET') || '-05:00';
const ES_TZ    = env.get('ES_TZ')         || 'Europe/Madrid';
const ES_OFF   = env.get('ES_TZ_OFFSET')  || '+02:00';

// Useful runtime information
const allowedTables = Array.from(new Set(flow.get('allowed_tables') || []));

const about = {
  name: NAME,
  version: VERSION,
  owner: OWNER,
  mission: MISSION,
  tone: TONE,
  safeguards: [GUARDS],
  models: { sql_generator: LLM_SQL, summarizer: LLM_SUMMARY },
  timezone: { app: APP_TZ, offset: APP_OFF, alt: { es: ES_TZ, offset: ES_OFF } },
  data: { tables_allowed: allowedTables },
  endpoints: [
    { method:'POST', path:'/ask',    body:'{ question: "…" }' },
    { method:'GET',  path:'/about' }
  ],
  samples: [
    'about',
    'Who are you?',
    'What happened to AH between 09:00 and 10:00 on 21/03/2025?',
    'Suggestions now',
    'T+RH trend over the last 50 readings'
  ]
};

msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = { ok:true, about, now: new Date().toISOString() };
return msg;

// ask_entry
// - Read msg.payload.question (a string).
// - If it is missing, return a structured error.
// - If the question asks about identity or capabilities,
//   reply directly without passing through SQL.

let q = '';

// 1) Extract the question
if (msg.payload && typeof msg.payload === 'object' && msg.payload.question) {
    q = String(msg.payload.question).trim();
} else if (typeof msg.payload === 'string') {
    // Alternative: allow the request body to be a plain string
    q = msg.payload.trim();
}

// 2) Return an error if no question is supplied
if (!q) {
    msg.payload = {
        answer: '❌ The "question" field is missing from the POST /ask body.',
        columns: [],
        rows: [],
        sql: '',
        via: 'web',
        suggestions: [
            'Example: {"question":"How many records are there today?"}'
        ]
    };
    // output 2 -> HTTP response
    return [null, msg];
}

// 3) Determine the channel (web / telegram / etc.)
if (msg.payload && typeof msg.payload === 'object' && msg.payload.via) {
    msg.via = String(msg.payload.via);
} else {
    msg.via = msg.via || 'web';
}

// 4) Normalise the question to detect the ABOUT intent
const qNorm = q
    .toLowerCase()
    .normalize('NFD')                // remove accents
    .replace(/[\u0300-\u036f]/g, ''); 

const isAbout =
    /quien eres\??/.test(qNorm) || // Spanish: who are you?
    /qu[eé] eres\??/.test(qNorm) || // Spanish: what are you?
    /que puedes hacer\??/.test(qNorm) || // Spanish: what can you do?
    /ayuda/.test(qNorm) || // Spanish: help
    /\babout\b/.test(qNorm) ||
    /\bwho are you\b/.test(qNorm) ||          
    /\bwhat can you do\b/.test(qNorm) ||      
    /\bhelp\b/.test(qNorm);                   

// 4.1) Detect the user language using a simple heuristic
function detectLang(text) {
  const t = (text || '').toLowerCase();

  // Strong Spanish-language cues; retain the original Spanish matching terms
  const hasEsChars = /[áéíóúñ¿¡]/.test(t);
  const esHits = (t.match(/\b(el|la|los|las|de|que|como|cómo|hoy|ayer|últim[oa]s?|promedio|temperatura|humedad|luz)\b/g) || []).length;

  // Strong English-language cues
    const enHits = (t.match(/\b(the|what|how|who|are|you|help|about|today|yesterday|last|average|temperature|humidity|light)\b/g) || []).length;


  if (hasEsChars || esHits > enHits) return 'es';
  if (enHits > esHits) return 'en';
  return 'es'; // Fallback: Spanish is the original system language
}

msg.userLang = detectLang(q);


// 5) Reply directly to identity/capability questions
if (isAbout) {
    const NAME    = env.get('ABOUT_NAME')    || 'QUILLAMA';
    const VERSION = env.get('ABOUT_VERSION') || '0.1.0';
    const OWNER   = env.get('ABOUT_OWNER')   || 'Quillaqua';

    const lang = (msg.userLang || 'es').toLowerCase();

    const MISSION = (env.get('ABOUT_MISSION') || 
        'Greenhouse climate analyst: I read the readings table, ' +
        'summarise the state, detect trends, and suggest actions.'
    ).trim();

    const TONE = (env.get('ABOUT_TONE') || 
        'Clear, concise, and actionable.'
    ).trim();

    msg.payload = {
        answer: (lang === 'en')
            ? `I'm ${NAME}, a data assistant for your greenhouse.

            • Version: ${VERSION}
            • Owner: ${OWNER}
            • Mission: ${MISSION}

            I read climate and actuator data from the database (table "lecturas"),
            turn your questions into safe SQL queries, and explain the results in plain language.

            I don't control the hardware directly: I only provide recommendations based on the data.
            My style is: ${TONE}`
                    : `I'm ${NAME}, a data assistant for your greenhouse.

            • Version: ${VERSION}
            • Owner: ${OWNER}
            • Mission: ${MISSION}

            I read climate and actuator data from the database (table "lecturas"),
            turn your questions into safe SQL queries, and explain the results in plain language.

            I don't control the hardware directly: I only provide recommendations based on the data.
            My style is: ${TONE}`,

        columns: [],
        rows: [],
        sql: '',          // no SQL is used in this reply
        via: msg.via,
        suggestions: [
            'Average T over the last 30 minutes',
            'T and RH trend over the last 50 readings',
            'What has VPD been like over the last hour?',
            'Which actuators were activated most often today?'
        ]
    };

    // output 2 -> direct HTTP response
    return [null, msg];
}

// 6) Normal case: save the question and continue to the NL→SQL flow
msg.userQuestion = q;
return [msg, null];

// Package the final response for the UI / Telegram

let content = '';

if (msg.payload && msg.payload.message && typeof msg.payload.message.content === 'string') {
    content = msg.payload.message.content;
} else if (typeof msg.payload === 'string') {
    content = msg.payload;
}

const answer = (content || '').trim() || 'No response from the AI.';

const rows = msg.rows || [];
const columns = msg.columns || [];
const sql = msg.sql || msg.topic || '';

msg.payload = {
    answer: answer,
    columns: columns,
    rows: rows,
    sql: sql,
    via: msg.via || 'web',
    suggestions: [] // currently empty; the UI may generate suggestions
    // quillama: null
};

return msg;

// Receive the Ollama reply and place the single SELECT statement passing validation in msg.sql.
// On failure, construct an error reply and use output 2.

function fail(reason, sqlText) {
    msg.payload = {
        answer: '❌ Could not generate a safe SQL query: ' + reason,
        columns: [],
        rows: [],
        sql: sqlText || '',
        via: msg.via || 'web',
        suggestions: [
            'Rephrase the question with more detail.',
            'Ask to see the SQL query directly.'
        ]
    };
    return [null, msg]; // output 2 -> HTTP response
}

let content = '';

if (msg.payload && msg.payload.message && typeof msg.payload.message.content === 'string') {
    content = msg.payload.message.content;
} else if (typeof msg.payload === 'string') {
    content = msg.payload;
}

if (!content) {
    return fail('empty model response.', '');
}

// Remove Markdown code fences
let sql = content.replace(/```sql/gi, '')
                 .replace(/```/g, '')
                 .trim();

// Collapse whitespace
sql = sql.replace(/\s+/g, ' ').trim();

// Correction for the light column:
// The database has no Luz column; greenhouse light is stored in L.
// If the model uses Luz (Spanish for light) as an identifier, replace it with L.
sql = sql.replace(/\bLuz\b/gi, 'L');

if (!sql) {
    return fail('empty response after cleaning.', '');
}

if (!/^select\b/i.test(sql)) {
    return fail('the query does not begin with SELECT.', sql);
}

// Split on ';'
const statements = sql.split(';').map(s => s.trim()).filter(Boolean);
if (statements.length !== 1) {
    return fail('multiple statements were detected; only one is allowed.', sql);
}

// Block the defined prohibited keywords
const forbidden = /\b(INSERT|UPDATE|DELETE|DROP|TRUNCATE|CREATE|ALTER|GRANT|REVOKE)\b/i;
if (forbidden.test(sql)) {
    return fail('prohibited SQL keywords were detected (INSERT/UPDATE/DELETE, etc.).', sql);
}

// SQL accepted by the implemented validator
msg.sql = sql;
msg.topic = sql; // for the mysql node

return [msg, null];

const rows = msg.payload || [];

// 1) Group columns by table
const byTable = {};
for (const r of rows) {
    const t = r.TABLE_NAME;
    if (!byTable[t]) byTable[t] = [];
    byTable[t].push({
        name: r.COLUMN_NAME,
        type: r.DATA_TYPE
    });
}

// 2) Build the schema text for the LLM
let lines = [];
lines.push("QDB database schema:");
for (const table of Object.keys(byTable).sort()) {
    lines.push(`\nTable ${table}:`);
    for (const col of byTable[table]) {
        lines.push(`- ${col.name} (${col.type})`);
    }
}

// Store the schema in global context
const schemaText = lines.join("\n");
global.set("dbSchema", schemaText);

// 3) Retain the existing allowed_tables context update
const present = new Set(rows.map(r => r.TABLE_NAME));
const strict = new Set(flow.get("allowed_tables") || [
  "lecturas","actuators","nutrient_readings","system_events",
  "v_current_status","v_last_24h","v_alarms","v_energy_security"
]);
flow.set("allowed_tables", [...[...strict].filter(t => present.has(t))]);

// Optionally display status information on the node
node.status({ text: "Schema: " + Array.from(present).join(", ") });

// Pass msg through so that the debug node can inspect the rows
return msg;

const DB = env.get('DB_NAME') || 'QDB';
msg.topic = `SELECT TABLE_NAME, COLUMN_NAME, DATA_TYPE
             FROM information_schema.COLUMNS
             WHERE TABLE_SCHEMA = '${DB}'
             ORDER BY TABLE_NAME, ORDINAL_POSITION;`;
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const sql = msg.sql || msg.topic || '';
const question = msg.userQuestion || '';

const columns = rows.length ? Object.keys(rows[0]) : [];
msg.rows = rows;
msg.columns = columns;

const MAX_ROWS_PREVIEW = 50;
const previewRows = rows.slice(0, MAX_ROWS_PREVIEW);

msg.headers = { 'Content-Type': 'application/json' };

// Language must already be set, ideally by ask_entry
const lang = (msg.userLang || 'es').toLowerCase();

const systemPrompt = (lang === 'en')
    ? `You are a data assistant who explains SQL query results to non-technical users.

Instructions:
- ALWAYS respond in English.
- Be direct: explain what the values mean (average, min, max, and whether it goes up, down, or stays stable).
- Do not talk about data formats (JSON, rows, records, columns, etc.) unless the user explicitly asks.
- If you see columns like vpd_min, vpd_max, vpd_avg (or similar), summarize the range and say if it looks stable or variable.
- If there is only one average value (e.g., clima_avg_today, light_avg_today, temp_avg_last_hour), give a short explanation of that value.
- If the result is empty, simply say no data was found for the requested period.`
    : `You are a data assistant who explains SQL query results to non-technical users.

Instructions:
- ALWAYS respond in neutral Spanish.
- Be direct: explain what the values mean (average, minimum, maximum, and whether they increase, decrease, or remain stable).
- Do not discuss data formats (JSON, rows, records, columns, etc.) unless the user explicitly asks.
- If you see columns such as vpd_min, vpd_max, vpd_prom (or similar), summarise the range and indicate whether it appears stable or variable.
- If there is only one average value (for example clima_prom_hoy, luz_promedio_hoy, temperatura_promedio_ultima_hora), give a short explanation of that value.
- If the result is empty, simply state that no data were found for the requested period.`;

const userBlock = (lang === 'en')
    ? `Original user question:
${question}

Executed SQL query:
${sql}

First ${previewRows.length} results in JSON:
${JSON.stringify(previewRows, null, 2)}

Total rows: ${rows.length}`
    : `Original user question:
${question}

Executed SQL query:
${sql}

First ${previewRows.length} results in JSON:
${JSON.stringify(previewRows, null, 2)}

Total rows: ${rows.length}`;

msg.payload = {
    model: 'qwen2.5:14b',
    stream: false,
    options: {
        temperature: 0,     // encourages adherence to the requested language
        num_ctx: 1024,
        num_predict: 220
    },
    messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userBlock }
    ]
};

return msg;

// Store the contents of lecturas_sinonimos.txt in global.dbSchema

const txt = typeof msg.payload === 'string' ? msg.payload : '';

global.set('dbSchema', txt);

node.status({ text: txt ? 'dbSchema loaded' : 'empty' });

return null;

// Store the file contents in global.sqlExamples

const txt = typeof msg.payload === 'string' ? msg.payload : '';

global.set('sqlExamples', txt);

node.status({ text: txt ? 'SQL examples loaded' : 'empty' });

return null;
